const enabled = $env.QF_N8N_TRANSPORT_ENABLED === 'true';
const baseUrl = ($env.QF_CORE_STAGING_BASE_URL || '').replace(/\/$/, '');
const workerId = $env.QF_N8N_WORKER_ID || '';
const inbound = $env.QF_N8N_TO_CORE_HMAC_SECRET || '';
const response = $env.QF_CORE_TO_N8N_HMAC_SECRET || '';
const configured = Boolean(
  enabled &&
  /^https:\/\//.test(baseUrl) &&
  /^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$/.test(workerId) &&
  inbound.length >= 32 &&
  response.length >= 32 &&
  inbound !== response
);
return [{ json: {
  phase: 'QF-MVP-50.2B',
  transportVersion: 1,
  configured,
  transportEnabled: enabled,
  secretSource: 'selfhost_env',
  baseUrlConfigured: /^https:\/\//.test(baseUrl),
  workerIdConfigured: /^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$/.test(workerId),
  inboundSecretConfigured: inbound.length >= 32,
  responseSecretConfigured: response.length >= 32,
  secretsDistinct: inbound.length >= 32 && response.length >= 32 && inbound !== response,
  workerId
} }];

const requestId = $json.requestId;
const workerId = $json.workerId;
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(requestId)) {
  throw new Error('QF_50_2B_REQUEST_ID_INVALID');
}
const timestamp = Math.floor(Date.now() / 1000);
const rawBody = JSON.stringify({ transportVersion: 1, requestId, workerId });
return [{ json: { ...$json, requestId, workerId, timestamp, rawBody } }];

const canonical = [
  'QF-AUTOMATION-TRANSPORT-V1',
  'N8N_TO_CORE',
  'POST',
  '/api/internal/automation/n8n/claim',
  $json.requestId,
  String($json.timestamp),
  $json.bodySha256
].join('\n');
return [{ json: { ...$json, requestCanonical: canonical } }];

// QF-MVP-50.2B-R1 signed transport. Replaces the HTTP Request node, whose raw-body +
// text + full-response combination serialises a live stream on n8n 2.32.7.
// Request signing stays upstream and response verification stays downstream: this node
// only performs the exchange and emits plain, fully-serialisable data.
const items = $input.all();
if (items.length !== 1) throw new Error('QF_50_2B_TRANSPORT_ITEM_COUNT_INVALID');
const input = items[0].json;
if (!input || typeof input !== 'object' || Array.isArray(input)) throw new Error('QF_50_2B_TRANSPORT_INPUT_INVALID');

// Reads that may hit a throwing accessor never escape un-sanitized.
const pick = (o, k) => { try { return o === null || o === undefined ? undefined : o[k]; } catch (_) { return undefined; } };
// Primitives only. A non-scalar is dropped, never stringified into '[object Object]'.
const scalar = (v) => (typeof v === 'string' ? v : (typeof v === 'number' && Number.isFinite(v)) ? String(v) : null);

const requestId = scalar(input.requestId);
const timestamp = scalar(input.timestamp);
const bodySha256 = scalar(input.bodySha256);
const requestHmac = scalar(input.requestHmac);
if (!requestId || !timestamp || !bodySha256 || !requestHmac) throw new Error('QF_50_2B_TRANSPORT_IDENTITY_INVALID');
if (/[\r\n\u0000]/.test(requestId + timestamp + bodySha256 + requestHmac)) throw new Error('QF_50_2B_TRANSPORT_IDENTITY_UNSAFE');

// rawBody is transmitted byte-for-byte: bodySha256 and the upstream signature are bound to
// these exact bytes. The two guards below only refuse inputs the HTTP layer would silently
// reshape (edge whitespace is trimmed, non-JSON is re-encoded) under a JSON content type.
const rawBody = input.rawBody;
if (typeof rawBody !== 'string' || rawBody.length === 0) throw new Error('QF_50_2B_TRANSPORT_RAW_BODY_INVALID');
if (rawBody !== rawBody.trim()) throw new Error('QF_50_2B_TRANSPORT_RAW_BODY_UNSTABLE');
try { JSON.parse(rawBody); } catch (_) { throw new Error('QF_50_2B_TRANSPORT_RAW_BODY_NOT_JSON'); }

const baseUrl = String($env.QF_CORE_STAGING_BASE_URL || '').replace(/\/$/, '');
if (!/^https:\/\//.test(baseUrl)) throw new Error('QF_50_2B_TRANSPORT_BASE_URL_INVALID');
const url = baseUrl + '/api/internal/automation/n8n/claim';

let httpResponse;
try {
  httpResponse = await this.helpers.httpRequest({
    method: 'POST',
    url: url,
    headers: {
      'content-type': 'application/json',
      'x-qf-transport-version': '1',
      'x-qf-request-id': requestId,
      'x-qf-timestamp': timestamp,
      'x-qf-body-sha256': bodySha256,
      'x-qf-signature': 'v1=' + requestHmac
    },
    body: rawBody,
    timeout: 10000,
    returnFullResponse: true,
    encoding: 'text',
    json: false,
    ignoreHttpStatusErrors: true,
    disableFollowRedirect: true
  });
} catch (error) {
  // Only a token-shaped code is surfaced. The original error object is discarded here:
  // it carries the request/agent graph that produced the circular-structure failure.
  const raw = pick(error, 'code');
  const code = typeof raw === 'string' && /^[A-Za-z0-9_]{1,40}$/.test(raw) ? raw : 'UNKNOWN';
  throw new Error('QF_50_2B_TRANSPORT_CALL_FAILED_' + code);
}

if (!httpResponse || typeof httpResponse !== 'object' || Array.isArray(httpResponse)) throw new Error('QF_50_2B_TRANSPORT_RESULT_INVALID');
const statusCode = pick(httpResponse, 'statusCode');
const body = pick(httpResponse, 'body');
const headersIn = pick(httpResponse, 'headers');
if (!Number.isInteger(statusCode)) throw new Error('QF_50_2B_TRANSPORT_STATUS_INVALID');
if (statusCode >= 300 && statusCode < 400) throw new Error('QF_50_2B_TRANSPORT_REDIRECT_REFUSED');
if (typeof body !== 'string') throw new Error('QF_50_2B_TRANSPORT_BODY_NOT_STRING');
if (!headersIn || typeof headersIn !== 'object' || Array.isArray(headersIn)) throw new Error('QF_50_2B_TRANSPORT_HEADERS_INVALID');

// Header values are copied out by value into a fresh object. A container that exposes no own
// enumerable entries is read through its iterator instead of degrading to an empty map.
let entries = Object.entries(headersIn);
if (entries.length === 0 && typeof pick(headersIn, 'entries') === 'function') {
  try { entries = Array.from(headersIn.entries()); } catch (_) { entries = []; }
}
const headers = {};
for (const pair of entries) {
  const name = String(pair[0]).toLowerCase();
  // A '__proto__' header name would assign through the prototype instead of landing on the
  // map, so it is refused outright. Core never signs one. First value wins for repeats.
  if (name === '__proto__') continue;
  if (Object.prototype.hasOwnProperty.call(headers, name)) continue;
  const value = pair[1];
  const normalized = Array.isArray(value) ? value.map(scalar).filter((x) => x !== null) : scalar(value);
  if (normalized === null) continue;
  headers[name] = normalized;
}
if (Object.keys(headers).length === 0) throw new Error('QF_50_2B_TRANSPORT_HEADERS_EMPTY');

const statusMessage = scalar(pick(httpResponse, 'statusMessage')) || '';

// Only these four plain fields leave this node. No request, socket, agent, config or client
// reference is carried forward, so nothing downstream can hold an unserialisable object.
return [{ json: { statusCode: statusCode, body: body, headers: headers, statusMessage: statusMessage } }];

const response = $json;
const headers = response.headers || {};
const rawBody = typeof response.body === 'string' ? response.body : JSON.stringify(response.body ?? '');
const h = {};
for (const [k, v] of Object.entries(headers)) h[String(k).toLowerCase()] = Array.isArray(v) ? String(v[0] ?? '') : String(v ?? '');
return [{ json: {
  requestId: $('Build Exact Claim Body').first().json.requestId,
  statusCode: Number(response.statusCode),
  rawResponseBody: rawBody,
  responseHeaders: h,
  responseVersion: h['x-qf-response-version'] || '',
  responseRequestId: h['x-qf-response-request-id'] || '',
  responseTimestamp: h['x-qf-response-timestamp'] || '',
  responseBodySha256Header: h['x-qf-response-body-sha256'] || '',
  responseSignature: h['x-qf-response-signature'] || ''
} }];

const ts = $json.responseTimestamp;
const canonical = [
  'QF-AUTOMATION-TRANSPORT-V1',
  'CORE_TO_N8N_RESPONSE',
  '/api/internal/automation/n8n/claim',
  $json.responseRequestId,
  ts,
  $json.actualResponseBodySha256
].join('\n');
return [{ json: { ...$json, responseCanonical: canonical } }];

const now = Math.floor(Date.now() / 1000);
const ts = Number($json.responseTimestamp);
const expectedSig = 'v1=' + $json.expectedResponseHmac;
const checks = {
  version: $json.responseVersion === '1',
  requestId: $json.responseRequestId === $json.requestId,
  timestamp: /^\d{10}$/.test($json.responseTimestamp) && Number.isSafeInteger(ts) && Math.abs(now - ts) <= 300,
  bodyHash: /^[0-9a-f]{64}$/.test($json.responseBodySha256Header) && $json.responseBodySha256Header === $json.actualResponseBodySha256,
  signature: /^v1=[0-9a-f]{64}$/.test($json.responseSignature) && $json.responseSignature === expectedSig,
  status: Number.isInteger($json.statusCode) && $json.statusCode >= 200 && $json.statusCode < 600
};
const verified = Object.values(checks).every(Boolean);
return [{ json: { ...$json, verified, checks } }];

let payload;
try { payload = JSON.parse($json.rawResponseBody); } catch { throw new Error('QF_50_2B_RESPONSE_JSON_INVALID'); }
if (!payload || typeof payload !== 'object' || payload.transportVersion !== 1 || payload.requestId !== $json.requestId) {
  throw new Error('QF_50_2B_RESPONSE_ENVELOPE_INVALID');
}
const allowedStates = new Set(['empty', 'claimed']);
if (!allowedStates.has(payload.state) || typeof payload.replayed !== 'boolean' || typeof payload.executable !== 'boolean') {
  throw new Error('QF_50_2B_RESPONSE_STATE_INVALID');
}
if ((payload.replayed || payload.state === 'empty') && payload.executable !== false) throw new Error('QF_50_2B_NONEXECUTABLE_INVARIANT');
return [{ json: { verified: true, claim: payload, routingEnabled: false, safeCode: 'QF_50_2B_SIGNED_HANDSHAKE_VERIFIED_ROUTING_DISABLED' } }];
